from functools import lru_cache
from typing import List

@lru_cache(maxsize=None)
def fib(k: int) -> int:
    """k-th Fibonacci number via fast doubling."""
    if k == 0:
        return 0
    a, b = 0, 1
    for bit in bin(k)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        a, b = (c, d) if bit == "0" else (d, c + d)
    return a

def v_p(n: int, p: int) -> int:
    """p-adic valuation of a nonzero integer n."""
    v = 0
    n = abs(n)
    while n % p == 0:
        n //= p
        v += 1
    return v

def rank_of_apparition(p: int, limit: int = 5000) -> int:
    """Least m >= 1 with p | F_m."""
    for m in range(1, limit + 1):
        if fib(m) % p == 0:
            return m
    raise RuntimeError("not found")

def valuation_staircase(p: int, R: int) -> List[int]:
    """v_p(F_{alpha * p^r}) for r = 0..R, alpha = rank of apparition."""
    alpha = rank_of_apparition(p)
    return [v_p(fib(alpha * p ** r), p) for r in range(R + 1)]

if __name__ == "__main__":
    for p in [3, 5, 7, 11, 13, 17]:
        print(f"p={p:2d}: {valuation_staircase(p, 4)}")

from math import comb
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(k: int) -> int:
    if k == 0:
        return 0
    a, b = 0, 1
    for bit in bin(k)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        a, b = (c, d) if bit == "0" else (d, c + d)
    return a

def rhs(m: int, n: int) -> int:
    """sum_{j<=n} C(n,j) F_m^{n-j} F_{m+1}^j F_j."""
    Fm, Fm1 = fib(m), fib(m + 1)
    return sum(comb(n, j) * Fm ** (n - j) * Fm1 ** j * fib(j) for j in range(n + 1))

def verify(max_m: int = 12, max_n: int = 12) -> bool:
    """Check F_{(m+1)n} == rhs(m,n) for all small m,n."""
    return all(fib((m + 1) * n) == rhs(m, n)
               for m in range(max_m + 1) for n in range(max_n + 1))

if __name__ == "__main__":
    print("multiple-index binomial expansion holds:", verify())
    print("F_{4*7} =", fib(4 * 7), "=", rhs(3, 7))

from math import factorial
from typing import Callable

def critical_length(base: Callable[[int], int], target: int, cap: int = 500) -> int:
    """Least n with prod_{k<n} base(k) > target."""
    prod = 1
    for n in range(cap + 1):
        if prod > target:
            return n
        prod *= base(n)
    raise RuntimeError("exceeded cap")

def factorial_threshold(target: int) -> int:
    """Least n with n! > target."""
    return critical_length(lambda i: i + 1, target)

if __name__ == "__main__":
    for N in [1, 10, 1000, 10**6, 10**9]:
        tau = factorial_threshold(N)
        print(f"N={N:>10}: tau={tau:2d}, {tau}!={factorial(tau)}")
    # slower-percolation comparison
    for name, b in [("factorial", lambda i: i + 1),
                    ("ternary", lambda i: 3),
                    ("binary", lambda i: 2)]:
        print(f"{name:>10}: tau(1000)={critical_length(b, 1000)}")

