from functools import lru_cache

@lru_cache(maxsize=None)
def fib(k: int) -> int:
    if k == 0:
        return 0
    a, b = 0, 1
    for bit in bin(k)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        a, b = (c, d) if bit == "0" else (d, c + d)
    return a

def fib_at_product_index(m: int, n: int) -> int:
    """Compute F_{(m+1)n} via the multiple-index binomial expansion instead of
    directly, using only F_m, F_{m+1} and small Fibonacci numbers F_j."""
    Fm, Fm1 = fib(m), fib(m + 1)
    return sum(comb(n, j) * Fm ** (n - j) * Fm1 ** j * fib(j) for j in range(n + 1))
